{
  "type": "playbook",
  "spec_version": "cacao-2.0",
  "id": "playbook--5e1f3c2a-0000-4000-8000-000000000001",
  "name": "Ransomware precursor on a workstation",
  "playbook_types": ["investigation", "mitigation"],
  "created_by": "identity--0b7c9d10-0000-4000-8000-000000000002",
  "created": "2026-10-01T09:00:00.000Z",
  "modified": "2026-11-02T14:30:00.000Z",
  "workflow_start": "start--a1",
  "workflow": {
    "start--a1": { "type": "start", "on_completion": "action--enrich" },
    "action--enrich": {
      "type": "action",
      "name": "Get host details from Secure Endpoint",
      "commands": [{ "type": "http-api",
                     "command": "GET /v1/computers?hostname=fin-ws-22.example.com" }],
      "on_completion": "if-condition--severity"
    },
    "if-condition--severity": {
      "type": "if-condition",
      "condition": "[incident.priority >= 800 AND host.isolation == 'not_isolated']",
      "on_true": "action--approve",
      "on_false": "end--z9"
    },
    "action--approve": {
      "type": "action",
      "name": "Analyst approves isolation",
      "commands": [{ "type": "manual",
                     "command": "Confirm business owner impact, then approve or reject" }],
      "on_completion": "action--isolate"
    },
    "action--isolate": {
      "type": "action",
      "name": "Isolate host",
      "commands": [{ "type": "http-api",
                     "command": "PUT /v1/computers/{connector_guid}/isolation" }],
      "on_completion": "end--z9"
    },
    "end--z9": { "type": "end" }
  }
}

